pub(crate) fn validate_revenue_solvency_outcome_floor_definition_packet(root: &Path) -> Result<(), String> {
    for path in [
        REVENUE_SOLVENCY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH,
        REVENUE_SOLVENCY_OUTCOME_FLOOR_DEFINITION_PACKET_SCHEMA_PATH,
        REVENUE_SOLVENCY_OUTCOME_FLOOR_DEFINITION_PACKET_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing revenue-solvency outcome floor definition packet artifact: {path}"
            ));
        }
    }

    let text =
        fs::read_to_string(root.join(REVENUE_SOLVENCY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH))
            .map_err(|e| e.to_string())?;
    let record: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&record, "record_id")? != "revenue-solvency-outcome-floor-definition-packet:v1"
        || string_field(&record, "record_family")?
            != "revenue_solvency_outcome_floor_definition_packet"
        || int_field(&record, "pulse")? != 165
        || string_field(&record, "lane_id")? != "revenue-solvency"
        || string_field(&record, "overlay_status")? != "non_additive_fiscal_control_overlay"
        || string_field(&record, "contract_path")? != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&record, "outcome_floor_thresholds_gap_path")?
            != OUTCOME_FLOOR_THRESHOLDS_GAP_JSON_PATH
        || string_field(
            &record,
            "income_security_family_outcome_floor_definition_packet_path",
        )? != INCOME_SECURITY_FAMILY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH
        || string_field(&record, "assigned_receipt_base_inventory_path")?
            != ASSIGNED_RECEIPT_BASE_INVENTORY_JSON_PATH
        || string_field(&record, "distributional_effect_placeholder_path")?
            != DISTRIBUTIONAL_EFFECT_PLACEHOLDER_JSON_PATH
        || string_field(&record, "lane_depth_explainability_tracker_path")?
            != LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH
    {
        return Err("revenue-solvency floor definition packet identity failed".to_string());
    }

    let status = record
        .get("source_custody_status")
        .and_then(serde_json::Value::as_object)
        .ok_or("revenue-solvency floor source custody status")?;
    for field in [
        "official_sources_only",
        "used_existing_captured_sources_only",
        "no_foia_or_records_request_submitted",
        "no_agency_or_person_contacted",
        "definition_packet_published",
    ] {
        if status.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!(
                "revenue-solvency floor status {field} must be true"
            ));
        }
    }
    for field in [
        "new_external_download_performed",
        "matched_receipt_bases_ready",
        "behavior_model_ready",
        "incidence_model_ready",
        "distribution_model_ready",
        "administration_model_ready",
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "pass_fail_review_complete",
        "rate_publication_ready",
        "solver_input_ready",
    ] {
        if status.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "revenue-solvency floor status {field} must be false"
            ));
        }
    }

    let policy = record
        .get("definition_policy")
        .and_then(serde_json::Value::as_object)
        .ok_or("revenue-solvency floor definition policy")?;
    for field in [
        "non_additive_overlay",
        "statutory_rates_cannot_be_published_before_base_behavior_incidence_distribution_and_administration",
        "all_lower_cost_scenarios_must_pass_floors",
        "missing_values_remain_null",
        "blocked_gates_remain_false",
        "named_floor_concepts_are_not_threshold_values",
        "international_differences_not_savings",
        "no_fraud_inference",
        "receipts_are_positive",
        "rates_do_not_need_to_sum_to_100_percent",
    ] {
        if policy.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!(
                "revenue-solvency floor policy {field} must be true"
            ));
        }
    }

    let classes = record
        .get("required_floor_classes")
        .and_then(serde_json::Value::as_array)
        .ok_or("revenue-solvency required floor classes")?;
    let expected_classes = [
        "access_coverage",
        "quality_safety",
        "equity_distribution",
        "adequacy_resilience",
        "fiscal_delivery_feasibility",
    ];
    if classes.len() != expected_classes.len() {
        return Err("revenue-solvency required floor class count failed".to_string());
    }
    let observed_classes = classes
        .iter()
        .map(|row| string_field(row, "floor_class"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected_class_set = expected_classes
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if observed_classes != expected_class_set {
        return Err("revenue-solvency required floor class set failed".to_string());
    }
    for row in classes {
        for field in [
            "threshold_value",
            "baseline_value",
            "policy_value",
            "stress_value",
        ] {
            if row.get(field) != Some(&serde_json::Value::Null) {
                return Err(format!("revenue-solvency floor class {field} must be null"));
            }
        }
        if row.get("passed").and_then(serde_json::Value::as_bool) != Some(false)
            || string_field(row, "review_status")? != "definition_only_not_thresholded"
        {
            return Err("revenue-solvency floor class must remain unpassed".to_string());
        }
    }

    let lane_floors = record
        .get("revenue_solvency_specific_floor_definitions")
        .and_then(serde_json::Value::as_array)
        .ok_or("revenue-solvency-specific floor definitions")?;
    let expected_lane_floors = [
        "distributional_progressivity",
        "revenue_stability",
        "administrability",
        "growth_sensitivity",
        "matched_base_behavior_incidence_readiness",
    ];
    if lane_floors.len() != expected_lane_floors.len() {
        return Err("revenue-solvency-specific floor count failed".to_string());
    }
    let observed_lane_floors = lane_floors
        .iter()
        .map(|row| string_field(row, "floor_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected_lane_floor_set = expected_lane_floors
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if observed_lane_floors != expected_lane_floor_set {
        return Err("revenue-solvency-specific floor set failed".to_string());
    }
    for row in lane_floors {
        if row.get("threshold_value") != Some(&serde_json::Value::Null)
            || row.get("observed_value") != Some(&serde_json::Value::Null)
            || row.get("passed").and_then(serde_json::Value::as_bool) != Some(false)
        {
            return Err(
                "revenue-solvency-specific floors must remain null and unpassed".to_string(),
            );
        }
    }

    for object_name in ["blocked_inputs", "blocked_outputs"] {
        let object = record
            .get(object_name)
            .and_then(serde_json::Value::as_object)
            .ok_or(object_name)?;
        if object
            .values()
            .any(|value| value != &serde_json::Value::Null)
        {
            return Err(format!("{object_name} must remain null"));
        }
    }

    let summary = record
        .get("summary")
        .and_then(serde_json::Value::as_object)
        .ok_or("revenue-solvency floor summary")?;
    if summary
        .get("floor_classes")
        .and_then(serde_json::Value::as_i64)
        != Some(5)
        || summary
            .get("revenue_solvency_specific_floors")
            .and_then(serde_json::Value::as_i64)
            != Some(5)
    {
        return Err("revenue-solvency floor summary counts failed".to_string());
    }
    for field in [
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "all_floors_passed",
        "rate_publication_ready",
        "solver_input_ready",
    ] {
        if summary.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "revenue-solvency floor summary {field} must be false"
            ));
        }
    }

    let claims = record
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("revenue-solvency floor claims")?;
    if claims
        .get("definition_packet_published")
        .and_then(serde_json::Value::as_bool)
        != Some(true)
    {
        return Err("revenue-solvency floor packet publication flag failed".to_string());
    }
    for field in [
        "matched_receipt_bases_ready",
        "behavior_model_ready",
        "incidence_model_ready",
        "distribution_model_ready",
        "administration_model_ready",
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "pass_fail_review_complete",
        "all_floors_passed",
        "statutory_rate_published",
        "effective_rate_published",
        "assigned_base_rate_published",
        "tax_proposal_published",
        "federal_effect_published",
        "gross_savings_published",
        "net_savings_published",
        "solver_input_ready",
        "solver_run_published",
        "public_rate_card_published",
        "department_cut_instruction_published",
        "technology_savings_claim_published",
        "balanced_budget_claim_published",
    ] {
        if claims.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "revenue-solvency floor claim {field} must be false"
            ));
        }
    }

    let reader =
        fs::read_to_string(root.join(REVENUE_SOLVENCY_OUTCOME_FLOOR_DEFINITION_PACKET_READER_PATH))
            .map_err(|e| e.to_string())?;
    for phrase in [
        REVENUE_SOLVENCY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH,
        "This revenue-solvency floor packet defines required floor concepts, but it does not set threshold values or pass/fail findings.",
        "Revenue-solvency is a non-additive overlay, not a savings lane.",
        "No statutory or effective rate can be published before matched receipt bases, behavior, incidence, distribution, and administration are modeled.",
        "No tax proposal, assigned-base rate, federal effect, gross savings, net savings, solver input, department-cut instruction, technology-savings claim, or balanced-budget claim is populated.",
        "No FOIA request, records request, form, email, phone call, or agency/person contact was submitted.",
        "not outcome-floor passage",
        "not a receipt-base model",
        "not an incidence model",
        "not a distributional score",
        "not a tax proposal",
        "not a rate calculation",
        "not solver input",
        "not a solver run",
        "not a savings estimate",
        "not a fraud finding",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(phrase) {
            return Err(format!(
                "revenue-solvency floor reader missing phrase: {phrase}"
            ));
        }
    }

    Ok(())
}

pub(crate) fn validate_revenue_solvency_total_receipts_floor_value_packet(root: &Path) -> Result<(), String> {
    for path in [
        REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_JSON_PATH,
        REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_SCHEMA_PATH,
        REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing revenue-solvency total-receipts floor-value artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(
        root.join(REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_JSON_PATH),
    )
    .map_err(|err| {
        format!(
            "failed to read {REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_JSON_PATH}: {err}"
        )
    })?;
    let record: serde_json::Value = serde_json::from_str(&text).map_err(|err| {
        format!(
            "failed to parse {REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_JSON_PATH}: {err}"
        )
    })?;

    if string_field(&record, "record_id")?
        != "revenue-solvency-total-receipts-floor-value-packet:v1"
        || string_field(&record, "record_family")?
            != "revenue_solvency_total_receipts_floor_value_packet"
        || int_field(&record, "pulse")? != 216
        || string_field(&record, "lane_id")? != "revenue-solvency"
        || string_field(&record, "overlay_status")? != "non_additive_fiscal_control_overlay"
        || string_field(&record, "floor_id")? != "revenue_stability"
        || string_field(&record, "floor_class")? != "adequacy_resilience"
        || string_field(&record, "floor_definition_packet_path")?
            != REVENUE_SOLVENCY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH
        || string_field(&record, "omb_receipt_category_context_path")?
            != OMB_RECEIPT_CATEGORY_FY2025_2031_CONTEXT_JSON_PATH
        || string_field(&record, "outcome_floor_wave_d_value_readiness_path")?
            != OUTCOME_FLOOR_WAVE_D_VALUE_READINESS_JSON_PATH
    {
        return Err("revenue-solvency total-receipts floor-value identity failed".to_string());
    }

    let threshold = record
        .get("threshold_rationale")
        .ok_or("revenue-solvency total-receipts threshold")?;
    if string_field(threshold, "rationale_id")?
        != "no-regression-from-fy2025-omb-total-receipts-baseline"
        || string_field(threshold, "selected_measure")?
            != "OMB Historical Table 2.1 FY2025 actual total receipts"
        || string_field(threshold, "threshold_type")? != "baseline_no_regression_floor"
        || number_field(threshold, "threshold_value")? != 5_236_421.0
        || string_field(threshold, "threshold_unit")? != "millions_usd"
        || string_field(threshold, "source_table")?
            != "OMB Historical Table 2.1 - Receipts by Source: 1934-2031"
        || !string_field(threshold, "review_status")?.contains("needs_role_review_before_pass_fail")
    {
        return Err("revenue-solvency total-receipts threshold failed".to_string());
    }

    let baseline = record
        .get("baseline_values")
        .ok_or("revenue-solvency total-receipts baseline")?;
    let primary = baseline
        .get("primary_baseline")
        .ok_or("revenue-solvency total-receipts primary baseline")?;
    if string_field(baseline, "reporting_period")? != "FY2025 actual"
        || string_field(primary, "measure")? != "total receipts"
        || number_field(primary, "value")? != 5_236_421.0
        || string_field(primary, "unit")? != "millions_usd"
        || string_field(primary, "source_id")? != "SRC-OMB-HIST-2-1-FY2027"
        || string_field(primary, "source_path")?
            != OMB_RECEIPT_CATEGORY_FY2025_2031_CONTEXT_JSON_PATH
        || !string_field(baseline, "boundary")?.contains("not a legal base")
        || !string_field(baseline, "boundary")?.contains("not a balanced-budget mechanism")
    {
        return Err("revenue-solvency total-receipts baseline failed".to_string());
    }
    let receipt_context = baseline
        .get("receipt_context")
        .and_then(serde_json::Value::as_array)
        .ok_or("revenue-solvency receipt context")?;
    let receipt_total = receipt_context
        .iter()
        .map(|row| number_field(row, "value"))
        .sum::<Result<f64, _>>()?;
    if receipt_context.len() != 5 || receipt_total != 5_236_421.0 {
        return Err("revenue-solvency receipt context total failed".to_string());
    }
    let custody = baseline
        .get("source_custody")
        .ok_or("revenue-solvency source custody")?;
    if string_field(custody, "publisher")? != "Office of Management and Budget"
        || string_field(custody, "raw_artifact_path")?
            != "data/raw/omb/SRC-OMB-HIST-2-1-FY2027/2026-06-21/hist02z1_fy2027.xlsx"
        || int_field(custody, "byte_count")? != 12_393
        || string_field(custody, "sha256")?
            != "1212da86947a71d9a0268e23d3de789402bcfb80b308cd48a32926a65b2e7bc3"
    {
        return Err("revenue-solvency total-receipts custody failed".to_string());
    }

    for field in ["policy_values", "stress_values", "pass_fail_evidence"] {
        if !record.get(field).is_some_and(serde_json::Value::is_null) {
            return Err(format!("revenue-solvency {field} must remain null"));
        }
    }
    let readiness = record
        .get("readiness_status")
        .and_then(serde_json::Value::as_object)
        .ok_or("revenue-solvency readiness")?;
    for field in [
        "threshold_rationale_ready",
        "threshold_value_populated",
        "baseline_value_ready",
    ] {
        if readiness.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!("revenue-solvency readiness {field} must be true"));
        }
    }
    for field in [
        "policy_value_ready",
        "stress_value_ready",
        "pass_fail_ready",
        "matched_receipt_bases_ready",
        "behavior_model_ready",
        "incidence_model_ready",
        "distribution_model_ready",
        "administration_model_ready",
        "solver_ready",
        "rate_ready",
    ] {
        if readiness.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "revenue-solvency readiness {field} must remain false"
            ));
        }
    }
    let blocked = record
        .get("blocked_outputs")
        .and_then(serde_json::Value::as_object)
        .ok_or("revenue-solvency blocked outputs")?;
    for (field, value) in blocked {
        if !value.is_null() {
            return Err(format!(
                "revenue-solvency blocked output {field} must remain null"
            ));
        }
    }
    let claims = record
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("revenue-solvency claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("revenue-solvency claim bool")?;
        if matches!(
            field.as_str(),
            "total_receipts_floor_value_packet_published"
                | "threshold_rationale_ready"
                | "threshold_value_populated"
                | "baseline_value_ready"
        ) {
            if !observed {
                return Err(format!("revenue-solvency claim {field} must be true"));
            }
        } else if observed {
            return Err(format!("revenue-solvency claim {field} must remain false"));
        }
    }

    let public_warning = string_field(&record, "public_warning")?;
    for required in [
        "draft no-regression revenue-solvency total-receipts floor threshold",
        "not matched receipt bases",
        "not a legal base",
        "not an economic base",
        "not incidence",
        "not distribution",
        "not administration burden",
        "not current-law solver yield",
        "not reform yield",
        "not policy values",
        "not stress values",
        "not pass/fail evidence",
        "not solver input",
        "not a statutory rate",
        "not an effective rate",
        "not an assigned-base rate",
        "not a tax proposal",
        "not a balanced-budget claim",
    ] {
        if !public_warning.contains(required) {
            return Err(format!(
                "revenue-solvency total-receipts warning missing {required}"
            ));
        }
    }

    let schema = fs::read_to_string(
        root.join(REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_SCHEMA_PATH),
    )
    .map_err(|err| {
        format!(
            "failed to read {REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_SCHEMA_PATH}: {err}"
        )
    })?;
    if !schema.contains("revenue_solvency_total_receipts_floor_value_packet") {
        return Err("revenue-solvency total-receipts schema missing record family".to_string());
    }

    let reader = fs::read_to_string(
        root.join(REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_READER_PATH),
    )
    .map_err(|err| {
        format!(
            "failed to read {REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_READER_PATH}: {err}"
        )
    })?;
    for required in [
        REVENUE_SOLVENCY_TOTAL_RECEIPTS_FLOOR_VALUE_PACKET_JSON_PATH,
        OMB_RECEIPT_CATEGORY_FY2025_2031_CONTEXT_JSON_PATH,
        "$5,236,421 million",
        "$2,656,044 million",
        "draft no-regression revenue-solvency total-receipts floor threshold",
        "not matched receipt bases",
        "policy and stress values remain null",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!(
                "revenue-solvency total-receipts reader missing {required}"
            ));
        }
    }

    Ok(())
}

pub(crate) fn validate_payment_integrity_outcome_floor_definition_packet(root: &Path) -> Result<(), String> {
    for path in [
        PAYMENT_INTEGRITY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH,
        PAYMENT_INTEGRITY_OUTCOME_FLOOR_DEFINITION_PACKET_SCHEMA_PATH,
        PAYMENT_INTEGRITY_OUTCOME_FLOOR_DEFINITION_PACKET_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing payment-integrity outcome floor definition packet artifact: {path}"
            ));
        }
    }

    let text =
        fs::read_to_string(root.join(PAYMENT_INTEGRITY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH))
            .map_err(|e| e.to_string())?;
    let record: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&record, "record_id")? != "payment-integrity-outcome-floor-definition-packet:v1"
        || string_field(&record, "record_family")?
            != "payment_integrity_outcome_floor_definition_packet"
        || int_field(&record, "pulse")? != 167
        || string_field(&record, "lane_id")? != "payment-integrity"
        || string_field(&record, "overlay_status")? != "non_additive_control_overlay"
        || string_field(&record, "contract_path")? != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&record, "outcome_floor_thresholds_gap_path")?
            != OUTCOME_FLOOR_THRESHOLDS_GAP_JSON_PATH
        || string_field(&record, "net_interest_outcome_floor_definition_packet_path")?
            != NET_INTEREST_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH
        || string_field(&record, "payment_integrity_depth_card_path")?
            != "data/derived/breadth_benchmark_matrix/payment_integrity_depth_card.fy2024.v1.draft.json"
        || string_field(&record, "lane_depth_explainability_tracker_path")?
            != LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH
    {
        return Err("payment-integrity floor definition packet identity failed".to_string());
    }

    let status = record
        .get("source_custody_status")
        .and_then(serde_json::Value::as_object)
        .ok_or("payment-integrity floor source custody status")?;
    for field in [
        "official_sources_only",
        "used_existing_captured_sources_only",
        "no_foia_or_records_request_submitted",
        "no_agency_or_person_contacted",
        "definition_packet_published",
    ] {
        if status.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!(
                "payment-integrity floor status {field} must be true"
            ));
        }
    }
    for field in [
        "new_external_download_performed",
        "causal_prevention_lineage_ready",
        "same_cohort_collection_lineage_ready",
        "program_component_review_ready",
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "pass_fail_review_complete",
        "savings_credit_ready",
        "solver_input_ready",
    ] {
        if status.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "payment-integrity floor status {field} must be false"
            ));
        }
    }

    let policy = record
        .get("definition_policy")
        .and_then(serde_json::Value::as_object)
        .ok_or("payment-integrity floor definition policy")?;
    for field in [
        "non_additive_overlay",
        "never_infer_fraud_from_improper_payment_estimate",
        "never_infer_fraud_from_international_comparison",
        "no_savings_credit_without_causal_prevention_or_same_cohort_collection_lineage",
        "all_lower_cost_scenarios_must_pass_floors",
        "missing_values_remain_null",
        "blocked_gates_remain_false",
        "named_floor_concepts_are_not_threshold_values",
        "international_differences_not_savings",
    ] {
        if policy.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!(
                "payment-integrity floor policy {field} must be true"
            ));
        }
    }

    let classes = record
        .get("required_floor_classes")
        .and_then(serde_json::Value::as_array)
        .ok_or("payment-integrity required floor classes")?;
    let expected_classes = [
        "access_coverage",
        "quality_safety",
        "equity_distribution",
        "adequacy_resilience",
        "fiscal_delivery_feasibility",
    ];
    if classes.len() != expected_classes.len() {
        return Err("payment-integrity required floor class count failed".to_string());
    }
    let observed_classes = classes
        .iter()
        .map(|row| string_field(row, "floor_class"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected_class_set = expected_classes
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if observed_classes != expected_class_set {
        return Err("payment-integrity required floor class set failed".to_string());
    }
    for row in classes {
        for field in [
            "threshold_value",
            "baseline_value",
            "policy_value",
            "stress_value",
        ] {
            if row.get(field) != Some(&serde_json::Value::Null) {
                return Err(format!(
                    "payment-integrity floor class {field} must be null"
                ));
            }
        }
        if row.get("passed").and_then(serde_json::Value::as_bool) != Some(false)
            || string_field(row, "review_status")? != "definition_only_not_thresholded"
        {
            return Err("payment-integrity floor class must remain unpassed".to_string());
        }
    }

    let lane_floors = record
        .get("payment_integrity_specific_floor_definitions")
        .and_then(serde_json::Value::as_array)
        .ok_or("payment-integrity-specific floor definitions")?;
    let expected_lane_floors = [
        "due_process",
        "timely_payment",
        "access",
        "false_positive_rate",
        "causal_prevention_or_same_cohort_collection_lineage",
    ];
    if lane_floors.len() != expected_lane_floors.len() {
        return Err("payment-integrity-specific floor count failed".to_string());
    }
    let observed_lane_floors = lane_floors
        .iter()
        .map(|row| string_field(row, "floor_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected_lane_floor_set = expected_lane_floors
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if observed_lane_floors != expected_lane_floor_set {
        return Err("payment-integrity-specific floor set failed".to_string());
    }
    for row in lane_floors {
        if row.get("threshold_value") != Some(&serde_json::Value::Null)
            || row.get("observed_value") != Some(&serde_json::Value::Null)
            || row.get("passed").and_then(serde_json::Value::as_bool) != Some(false)
        {
            return Err(
                "payment-integrity-specific floors must remain null and unpassed".to_string(),
            );
        }
    }

    for object_name in ["blocked_inputs", "blocked_outputs"] {
        let object = record
            .get(object_name)
            .and_then(serde_json::Value::as_object)
            .ok_or(object_name)?;
        if object
            .values()
            .any(|value| value != &serde_json::Value::Null)
        {
            return Err(format!("{object_name} must remain null"));
        }
    }

    let summary = record
        .get("summary")
        .and_then(serde_json::Value::as_object)
        .ok_or("payment-integrity floor summary")?;
    if summary
        .get("floor_classes")
        .and_then(serde_json::Value::as_i64)
        != Some(5)
        || summary
            .get("payment_integrity_specific_floors")
            .and_then(serde_json::Value::as_i64)
            != Some(5)
    {
        return Err("payment-integrity floor summary counts failed".to_string());
    }
    for field in [
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "all_floors_passed",
        "savings_credit_ready",
        "solver_input_ready",
    ] {
        if summary.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "payment-integrity floor summary {field} must be false"
            ));
        }
    }

    let claims = record
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("payment-integrity floor claims")?;
    if claims
        .get("definition_packet_published")
        .and_then(serde_json::Value::as_bool)
        != Some(true)
    {
        return Err("payment-integrity floor packet publication flag failed".to_string());
    }
    for field in [
        "causal_prevention_lineage_ready",
        "same_cohort_collection_lineage_ready",
        "program_component_review_ready",
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "pass_fail_review_complete",
        "all_floors_passed",
        "fraud_finding_published",
        "waste_finding_published",
        "recoverable_savings_credit_published",
        "federal_effect_published",
        "gross_savings_published",
        "net_savings_published",
        "solver_input_ready",
        "solver_run_published",
        "public_rate_card_published",
        "department_cut_instruction_published",
        "technology_savings_claim_published",
        "balanced_budget_claim_published",
    ] {
        if claims.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "payment-integrity floor claim {field} must be false"
            ));
        }
    }

    let reader = fs::read_to_string(
        root.join(PAYMENT_INTEGRITY_OUTCOME_FLOOR_DEFINITION_PACKET_READER_PATH),
    )
    .map_err(|e| e.to_string())?;
    for phrase in [
        PAYMENT_INTEGRITY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH,
        "This payment-integrity floor packet defines required floor concepts, but it does not set threshold values or pass/fail findings.",
        "Payment integrity is a non-additive overlay, not a savings lane.",
        "Never infer fraud from an improper-payment estimate or international comparison.",
        "No savings credit is available without causal prevention evidence or same-cohort collection lineage.",
        "No fraud finding, waste finding, recoverable savings credit, federal effect, gross savings, net savings, solver input, department-cut instruction, technology-savings claim, or balanced-budget claim is populated.",
        "No FOIA request, records request, form, email, phone call, or agency/person contact was submitted.",
        "not outcome-floor passage",
        "not a fraud finding",
        "not a waste finding",
        "not a recoverable savings estimate",
        "not a federal score",
        "not a target-cost selection",
        "not solver input",
        "not a solver run",
        "not a rate calculation",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(phrase) {
            return Err(format!(
                "payment-integrity floor reader missing phrase: {phrase}"
            ));
        }
    }

    Ok(())
}

pub(crate) fn validate_payment_integrity_fcic_payment_accuracy_floor_value_packet(
    root: &Path,
) -> Result<(), String> {
    for path in [
        PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_JSON_PATH,
        PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_SCHEMA_PATH,
        PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing payment-integrity FCIC floor-value artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(
        root.join(PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_JSON_PATH),
    )
    .map_err(|err| {
        format!(
            "failed to read {PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_JSON_PATH}: {err}"
        )
    })?;
    let record: serde_json::Value = serde_json::from_str(&text).map_err(|err| {
        format!(
            "failed to parse {PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_JSON_PATH}: {err}"
        )
    })?;

    if string_field(&record, "record_id")?
        != "payment-integrity-fcic-payment-accuracy-floor-value-packet:v1"
        || string_field(&record, "record_family")?
            != "payment_integrity_fcic_payment_accuracy_floor_value_packet"
        || string_field(&record, "status")?
            != "draft_threshold_and_baseline_values_ready_policy_stress_pass_fail_blocked"
        || int_field(&record, "pulse")? != 215
        || string_field(&record, "lane_id")? != "payment-integrity"
        || string_field(&record, "overlay_status")? != "non_additive_control_overlay"
        || string_field(&record, "program_id")? != "usda-federal-crop-insurance"
        || string_field(&record, "floor_id")? != "payment_accuracy"
        || string_field(&record, "floor_class")? != "quality_safety"
        || string_field(&record, "floor_definition_packet_path")?
            != PAYMENT_INTEGRITY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH
        || string_field(
            &record,
            "federal_crop_insurance_payment_integrity_bridge_path",
        )? != FCIC_PAYMENT_INTEGRITY_BRIDGE_JSON_PATH
        || string_field(&record, "outcome_floor_wave_d_value_readiness_path")?
            != OUTCOME_FLOOR_WAVE_D_VALUE_READINESS_JSON_PATH
    {
        return Err("payment-integrity FCIC floor-value identity failed".to_string());
    }

    let threshold = record
        .get("threshold_rationale")
        .ok_or("payment-integrity FCIC threshold rationale")?;
    if string_field(threshold, "rationale_id")?
        != "no-regression-from-fy2024-fcic-payment-accuracy-baseline"
        || string_field(threshold, "selected_measure")?
            != "Federal Crop Insurance Corporation FY2024 payment accuracy rate"
        || string_field(threshold, "threshold_type")? != "baseline_no_regression_floor"
        || (number_field(threshold, "threshold_value")? - 97.5725794).abs() > 0.000001
        || string_field(threshold, "threshold_unit")? != "percent"
        || string_field(threshold, "source_table")?
            != "PaymentAccuracy FY2024 All Program Results row 1422"
        || !string_field(threshold, "review_status")?.contains("needs_role_review_before_pass_fail")
        || !string_field(threshold, "why_this_measure")?.contains("not a savings basis")
    {
        return Err("payment-integrity FCIC threshold rationale failed".to_string());
    }

    let baseline = record
        .get("baseline_values")
        .ok_or("payment-integrity FCIC baseline values")?;
    let primary = baseline
        .get("primary_baseline")
        .ok_or("payment-integrity FCIC primary baseline")?;
    if string_field(baseline, "reporting_period")? != "FY2024"
        || string_field(baseline, "measurement_window")?
            != "2021-07 through 2022-06 reinsurance year 2022"
        || string_field(primary, "measure")? != "FCIC payment accuracy rate"
        || (number_field(primary, "value")? - 97.5725794).abs() > 0.000001
        || string_field(primary, "unit")? != "percent"
        || (number_field(primary, "outlays_millions")? - 23_867.31).abs() > 0.000001
        || (number_field(primary, "properly_paid_millions")? - 23_287.95).abs() > 0.000001
        || string_field(primary, "source_path")? != FCIC_PAYMENT_INTEGRITY_BRIDGE_JSON_PATH
        || !string_field(baseline, "boundary")?.contains("not a savings estimate")
    {
        return Err("payment-integrity FCIC baseline values failed".to_string());
    }
    let source_ids = primary
        .get("source_ids")
        .and_then(serde_json::Value::as_array)
        .ok_or("payment-integrity FCIC source ids")?
        .iter()
        .filter_map(serde_json::Value::as_str)
        .collect::<BTreeSet<_>>();
    if source_ids
        != BTreeSet::from([
            "SRC-OMB-PAYMENTACCURACY-FY2024-DATA",
            FCIC_SCORECARD_SOURCE_ID,
            FCIC_COM_23_SOURCE_ID,
            FCIC_SRA_2022_SOURCE_ID,
        ])
    {
        return Err("payment-integrity FCIC source ids failed".to_string());
    }
    let supporting_context = baseline
        .get("supporting_context")
        .and_then(serde_json::Value::as_array)
        .ok_or("payment-integrity FCIC supporting context")?;
    if supporting_context.len() != 6
        || !supporting_context.iter().any(|row| {
            string_field(row, "measure").ok().as_deref() == Some("FCIC improper payment rate")
                && (number_field(row, "amount_millions").unwrap_or_default() - 579.36).abs()
                    <= 0.000001
        })
        || !supporting_context.iter().any(|row| {
            string_field(row, "measure").ok().as_deref() == Some("RMA FY2024 sample policy count")
                && number_field(row, "value").unwrap_or_default() == 326.0
        })
    {
        return Err("payment-integrity FCIC supporting context failed".to_string());
    }

    for field in ["policy_values", "stress_values", "pass_fail_evidence"] {
        if !record.get(field).is_some_and(serde_json::Value::is_null) {
            return Err(format!("payment-integrity FCIC {field} must remain null"));
        }
    }
    let readiness = record
        .get("readiness_status")
        .and_then(serde_json::Value::as_object)
        .ok_or("payment-integrity FCIC readiness")?;
    for field in [
        "threshold_rationale_ready",
        "threshold_value_populated",
        "baseline_value_ready",
    ] {
        if readiness.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!(
                "payment-integrity FCIC readiness {field} must be true"
            ));
        }
    }
    for field in [
        "policy_value_ready",
        "stress_value_ready",
        "pass_fail_ready",
        "lower_cost_scenario_admissible",
        "savings_credit_ready",
        "solver_ready",
        "rate_ready",
    ] {
        if readiness.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "payment-integrity FCIC readiness {field} must remain false"
            ));
        }
    }
    let blocked = record
        .get("blocked_outputs")
        .and_then(serde_json::Value::as_object)
        .ok_or("payment-integrity FCIC blocked outputs")?;
    for (field, value) in blocked {
        if !value.is_null() {
            return Err(format!(
                "payment-integrity FCIC blocked output {field} must remain null"
            ));
        }
    }
    let claims = record
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("payment-integrity FCIC claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("payment-integrity FCIC claim bool")?;
        if matches!(
            field.as_str(),
            "fcic_payment_accuracy_floor_value_packet_published"
                | "threshold_rationale_ready"
                | "threshold_value_populated"
                | "baseline_value_ready"
        ) {
            if !observed {
                return Err(format!("payment-integrity FCIC claim {field} must be true"));
            }
        } else if observed {
            return Err(format!(
                "payment-integrity FCIC claim {field} must remain false"
            ));
        }
    }

    let public_warning = string_field(&record, "public_warning")?;
    for required in [
        "draft no-regression FCIC payment-accuracy floor threshold",
        "not a false-positive model",
        "not due-process evidence",
        "not policy values",
        "not stress values",
        "not pass/fail evidence",
        "not causal-prevention lineage",
        "not same-cohort collection lineage",
        "not fraud",
        "not waste",
        "not gross savings",
        "not net savings",
        "not a balanced-budget claim",
    ] {
        if !public_warning.contains(required) {
            return Err(format!(
                "payment-integrity FCIC public warning missing {required}"
            ));
        }
    }

    let schema = fs::read_to_string(
        root.join(PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_SCHEMA_PATH),
    )
    .map_err(|err| {
        format!(
            "failed to read {PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_SCHEMA_PATH}: {err}"
        )
    })?;
    if !schema.contains("payment_integrity_fcic_payment_accuracy_floor_value_packet") {
        return Err("payment-integrity FCIC schema missing record family".to_string());
    }

    let reader = fs::read_to_string(
        root.join(PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_READER_PATH),
    )
    .map_err(|err| {
        format!(
            "failed to read {PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_READER_PATH}: {err}"
        )
    })?;
    for required in [
        PAYMENT_INTEGRITY_FCIC_PAYMENT_ACCURACY_FLOOR_VALUE_PACKET_JSON_PATH,
        FCIC_PAYMENT_INTEGRITY_BRIDGE_JSON_PATH,
        "97.5725794 percent",
        "$579.36 million",
        "326 policies",
        "draft no-regression FCIC payment-accuracy floor threshold",
        "not a false-positive model",
        "policy and stress values remain null",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("payment-integrity FCIC reader missing {required}"));
        }
    }

    Ok(())
}

pub(crate) fn validate_veterans_outcome_floor_definition_packet(root: &Path) -> Result<(), String> {
    for path in [
        VETERANS_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH,
        VETERANS_OUTCOME_FLOOR_DEFINITION_PACKET_SCHEMA_PATH,
        VETERANS_OUTCOME_FLOOR_DEFINITION_PACKET_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing veterans outcome floor definition packet artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(root.join(VETERANS_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let record: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&record, "record_id")? != "veterans-outcome-floor-definition-packet:v1"
        || string_field(&record, "record_family")? != "veterans_outcome_floor_definition_packet"
        || int_field(&record, "pulse")? != 168
        || string_field(&record, "lane_id")? != "veterans"
        || string_field(&record, "contract_path")? != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&record, "outcome_floor_thresholds_gap_path")?
            != OUTCOME_FLOOR_THRESHOLDS_GAP_JSON_PATH
        || string_field(
            &record,
            "payment_integrity_outcome_floor_definition_packet_path",
        )? != PAYMENT_INTEGRITY_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH
        || string_field(&record, "veterans_depth_card_path")? != VETERANS_DEPTH_CARD_JSON_PATH
        || string_field(&record, "lane_depth_explainability_tracker_path")?
            != LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH
    {
        return Err("veterans floor definition packet identity failed".to_string());
    }

    let status = record
        .get("source_custody_status")
        .and_then(serde_json::Value::as_object)
        .ok_or("veterans floor source custody status")?;
    for field in [
        "official_sources_only",
        "used_existing_captured_sources_only",
        "no_foia_or_records_request_submitted",
        "no_agency_or_person_contacted",
        "definition_packet_published",
    ] {
        if status.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!("veterans floor status {field} must be true"));
        }
    }
    for field in [
        "new_external_download_performed",
        "eligible_cohort_model_ready",
        "service_package_model_ready",
        "statutory_continuity_review_ready",
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "pass_fail_review_complete",
        "target_cost_ready",
        "solver_input_ready",
    ] {
        if status.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!("veterans floor status {field} must be false"));
        }
    }

    let policy = record
        .get("definition_policy")
        .and_then(serde_json::Value::as_object)
        .ok_or("veterans floor definition policy")?;
    for field in [
        "statutory_continuity_required",
        "earned_eligibility_must_be_preserved_or_explicitly_reviewed",
        "eligible_cohort_and_service_package_required_before_target_cost",
        "all_lower_cost_scenarios_must_pass_floors",
        "missing_values_remain_null",
        "blocked_gates_remain_false",
        "named_floor_concepts_are_not_threshold_values",
        "international_differences_not_savings",
        "no_fraud_inference",
    ] {
        if policy.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!("veterans floor policy {field} must be true"));
        }
    }

    let classes = record
        .get("required_floor_classes")
        .and_then(serde_json::Value::as_array)
        .ok_or("veterans required floor classes")?;
    let expected_classes = [
        "access_coverage",
        "quality_safety",
        "equity_distribution",
        "adequacy_resilience",
        "fiscal_delivery_feasibility",
    ];
    if classes.len() != expected_classes.len() {
        return Err("veterans required floor class count failed".to_string());
    }
    let observed_classes = classes
        .iter()
        .map(|row| string_field(row, "floor_class"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected_class_set = expected_classes
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if observed_classes != expected_class_set {
        return Err("veterans required floor class set failed".to_string());
    }
    for row in classes {
        for field in [
            "threshold_value",
            "baseline_value",
            "policy_value",
            "stress_value",
        ] {
            if row.get(field) != Some(&serde_json::Value::Null) {
                return Err(format!("veterans floor class {field} must be null"));
            }
        }
        if row.get("passed").and_then(serde_json::Value::as_bool) != Some(false)
            || string_field(row, "review_status")? != "definition_only_not_thresholded"
        {
            return Err("veterans floor class must remain unpassed".to_string());
        }
    }

    let lane_floors = record
        .get("veterans_specific_floor_definitions")
        .and_then(serde_json::Value::as_array)
        .ok_or("veterans-specific floor definitions")?;
    let expected_lane_floors = [
        "earned_eligibility",
        "health_access",
        "claims_timeliness",
        "housing_and_employment_outcomes",
        "eligible_cohort_service_package_feasibility",
    ];
    if lane_floors.len() != expected_lane_floors.len() {
        return Err("veterans-specific floor count failed".to_string());
    }
    let observed_lane_floors = lane_floors
        .iter()
        .map(|row| string_field(row, "floor_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected_lane_floor_set = expected_lane_floors
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if observed_lane_floors != expected_lane_floor_set {
        return Err("veterans-specific floor set failed".to_string());
    }
    for row in lane_floors {
        if row.get("threshold_value") != Some(&serde_json::Value::Null)
            || row.get("observed_value") != Some(&serde_json::Value::Null)
            || row.get("passed").and_then(serde_json::Value::as_bool) != Some(false)
        {
            return Err("veterans-specific floors must remain null and unpassed".to_string());
        }
    }

    for object_name in ["blocked_inputs", "blocked_outputs"] {
        let object = record
            .get(object_name)
            .and_then(serde_json::Value::as_object)
            .ok_or(object_name)?;
        if object
            .values()
            .any(|value| value != &serde_json::Value::Null)
        {
            return Err(format!("{object_name} must remain null"));
        }
    }

    let summary = record
        .get("summary")
        .and_then(serde_json::Value::as_object)
        .ok_or("veterans floor summary")?;
    if summary
        .get("floor_classes")
        .and_then(serde_json::Value::as_i64)
        != Some(5)
        || summary
            .get("veterans_specific_floors")
            .and_then(serde_json::Value::as_i64)
            != Some(5)
    {
        return Err("veterans floor summary counts failed".to_string());
    }
    for field in [
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "all_floors_passed",
        "target_cost_ready",
        "solver_input_ready",
    ] {
        if summary.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!("veterans floor summary {field} must be false"));
        }
    }

    let claims = record
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("veterans floor claims")?;
    if claims
        .get("definition_packet_published")
        .and_then(serde_json::Value::as_bool)
        != Some(true)
    {
        return Err("veterans floor packet publication flag failed".to_string());
    }
    for field in [
        "eligible_cohort_model_ready",
        "service_package_model_ready",
        "statutory_continuity_review_ready",
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "pass_fail_review_complete",
        "all_floors_passed",
        "target_cost_published",
        "federal_effect_published",
        "gross_savings_published",
        "net_savings_published",
        "solver_input_ready",
        "solver_run_published",
        "public_rate_card_published",
        "department_cut_instruction_published",
        "technology_savings_claim_published",
        "balanced_budget_claim_published",
    ] {
        if claims.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!("veterans floor claim {field} must be false"));
        }
    }

    let reader =
        fs::read_to_string(root.join(VETERANS_OUTCOME_FLOOR_DEFINITION_PACKET_READER_PATH))
            .map_err(|e| e.to_string())?;
    for phrase in [
        VETERANS_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH,
        "This veterans floor packet defines required floor concepts, but it does not set threshold values or pass/fail findings.",
        "No lower-cost veterans scenario is admissible until earned eligibility, health access, claims timeliness, housing/employment outcomes, statutory continuity, equity, adequacy/resilience, and delivery-feasibility floors are thresholded, sourced, reviewed, and passed.",
        "No target cost can be selected without an eligible cohort, service package, statutory continuity review, transition cost, and delivery feasibility model.",
        "No target cost, federal effect, gross savings, net savings, solver input, department-cut instruction, technology-savings claim, or balanced-budget claim is populated.",
        "No FOIA request, records request, form, email, phone call, or agency/person contact was submitted.",
        "not outcome-floor passage",
        "not an eligible cohort model",
        "not a service package model",
        "not a statutory continuity finding",
        "not a federal score",
        "not a target-cost selection",
        "not solver input",
        "not a solver run",
        "not a rate calculation",
        "not a savings estimate",
        "not a fraud finding",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(phrase) {
            return Err(format!("veterans floor reader missing phrase: {phrase}"));
        }
    }

    Ok(())
}

pub(crate) fn validate_veterans_claims_backlog_floor_value_packet(root: &Path) -> Result<(), String> {
    for path in [
        VETERANS_CLAIMS_BACKLOG_FLOOR_VALUE_PACKET_JSON_PATH,
        VETERANS_CLAIMS_BACKLOG_FLOOR_VALUE_PACKET_SCHEMA_PATH,
        VETERANS_CLAIMS_BACKLOG_FLOOR_VALUE_PACKET_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing Veterans claims backlog floor value packet artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(root.join(VETERANS_CLAIMS_BACKLOG_FLOOR_VALUE_PACKET_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let record: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&record, "record_id")? != "veterans-claims-backlog-floor-value-packet:v1"
        || string_field(&record, "record_family")? != "veterans_claims_backlog_floor_value_packet"
        || int_field(&record, "pulse")? != 214
        || string_field(&record, "lane_id")? != "veterans"
        || string_field(&record, "floor_id")? != "claims_timeliness"
        || string_field(&record, "floor_definition_packet_path")?
            != VETERANS_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH
        || string_field(&record, "veterans_depth_card_path")? != VETERANS_DEPTH_CARD_JSON_PATH
        || string_field(&record, "outcome_floor_wave_d_value_readiness_path")?
            != OUTCOME_FLOOR_WAVE_D_VALUE_READINESS_JSON_PATH
    {
        return Err("Veterans claims backlog floor value packet identity failed".to_string());
    }

    let threshold = record
        .get("threshold_rationale")
        .ok_or("Veterans claims backlog threshold rationale")?;
    if string_field(threshold, "rationale_id")? != "no-regression-from-va-claims-backlog-probe"
        || string_field(threshold, "selected_measure")?
            != "VA compensation and pension rating bundle claims backlog"
        || string_field(threshold, "threshold_type")? != "baseline_no_regression_ceiling"
        || int_field(threshold, "threshold_value")? != 68207
        || string_field(threshold, "threshold_unit")? != "claims"
        || string_field(threshold, "source_table")? != "VA Detailed Claims Data dashboard"
        || !string_field(threshold, "review_status")?.contains("needs_role_review_before_pass_fail")
    {
        return Err("Veterans claims backlog threshold rationale failed".to_string());
    }

    let baseline = record
        .get("baseline_values")
        .ok_or("Veterans claims backlog baseline values")?;
    let primary = baseline
        .get("primary_baseline")
        .ok_or("Veterans claims backlog primary baseline")?;
    if string_field(baseline, "observed_date")? != "2026-06-30"
        || string_field(primary, "measure")?
            != "Compensation and pension rating bundle claims backlog"
        || int_field(primary, "value")? != 68207
        || string_field(primary, "unit")? != "claims"
        || string_field(primary, "source_id")? != "SRC-VA-CLAIMS-DATA"
        || string_field(primary, "source_path")? != VETERANS_DEPTH_CARD_JSON_PATH
        || string_field(primary, "status")? != "probe_not_performance_finding"
    {
        return Err("Veterans claims backlog primary baseline failed".to_string());
    }
    let supporting = baseline
        .get("supporting_context")
        .and_then(serde_json::Value::as_array)
        .ok_or("Veterans claims backlog supporting context")?;
    if supporting.len() != 1
        || string_field(&supporting[0], "measure")?
            != "Compensation and pension claim-based quality"
        || (number_field(&supporting[0], "value")? - 84.91).abs() > 0.000001
        || !string_field(baseline, "boundary")?.contains("not savings evidence")
    {
        return Err("Veterans claims backlog supporting context failed".to_string());
    }

    for field in ["policy_values", "stress_values", "pass_fail_evidence"] {
        if !record.get(field).is_some_and(serde_json::Value::is_null) {
            return Err(format!(
                "Veterans claims backlog field must stay null: {field}"
            ));
        }
    }

    let readiness = record
        .get("readiness_status")
        .ok_or("Veterans claims backlog readiness")?;
    for field in [
        "threshold_rationale_ready",
        "threshold_value_populated",
        "baseline_value_ready",
    ] {
        if !bool_field(readiness, field)? {
            return Err(format!(
                "Veterans claims backlog readiness should be true: {field}"
            ));
        }
    }
    for field in [
        "policy_value_ready",
        "stress_value_ready",
        "pass_fail_ready",
        "lower_cost_scenario_admissible",
        "solver_ready",
        "rate_ready",
    ] {
        if bool_field(readiness, field)? {
            return Err(format!(
                "Veterans claims backlog readiness must remain false: {field}"
            ));
        }
    }

    let blocked = record
        .get("blocked_outputs")
        .and_then(serde_json::Value::as_object)
        .ok_or("Veterans claims backlog blocked outputs")?;
    for (field, value) in blocked {
        if !value.is_null() {
            return Err(format!(
                "Veterans claims backlog blocked output must be null: {field}"
            ));
        }
    }

    let claims = record
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("Veterans claims backlog claims")?;
    for (field, value) in claims {
        let observed = value
            .as_bool()
            .ok_or("Veterans claims backlog claim bool")?;
        match field.as_str() {
            "claims_backlog_floor_value_packet_published"
            | "threshold_rationale_ready"
            | "threshold_value_populated"
            | "baseline_value_ready" => {
                if !observed {
                    return Err(format!(
                        "Veterans claims backlog claim should be true: {field}"
                    ));
                }
            }
            _ if observed => {
                return Err(format!(
                    "Veterans claims backlog downstream claim must be false: {field}"
                ));
            }
            _ => {}
        }
    }

    let warning = string_field(&record, "public_warning")?;
    for required in [
        "draft no-regression claims-backlog floor threshold",
        "not a complete claims-timeliness series",
        "not appeals evidence",
        "not policy values",
        "not stress values",
        "not pass/fail evidence",
        "not lower-cost scenario admissibility",
        "not solver input",
        "not rate calculation",
        "not gross savings",
        "not net savings",
        "not a balanced-budget claim",
    ] {
        if !warning.contains(required) {
            return Err(format!(
                "Veterans claims backlog warning missing: {required}"
            ));
        }
    }

    let reader =
        fs::read_to_string(root.join(VETERANS_CLAIMS_BACKLOG_FLOOR_VALUE_PACKET_READER_PATH))
            .map_err(|e| e.to_string())?;
    for required in [
        VETERANS_CLAIMS_BACKLOG_FLOOR_VALUE_PACKET_JSON_PATH,
        "68,207 claims",
        "84.91 percent",
        "draft no-regression Veterans claims-backlog floor",
        "policy and stress values remain null",
        "not a complete claims-timeliness series",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!(
                "Veterans claims backlog reader missing: {required}"
            ));
        }
    }

    Ok(())
}

pub(crate) fn validate_disaster_resilience_outcome_floor_definition_packet(root: &Path) -> Result<(), String> {
    for path in [
        DISASTER_RESILIENCE_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH,
        DISASTER_RESILIENCE_OUTCOME_FLOOR_DEFINITION_PACKET_SCHEMA_PATH,
        DISASTER_RESILIENCE_OUTCOME_FLOOR_DEFINITION_PACKET_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing disaster/resilience outcome floor definition packet artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(
        root.join(DISASTER_RESILIENCE_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH),
    )
    .map_err(|e| e.to_string())?;
    let record: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&record, "record_id")?
        != "disaster-resilience-outcome-floor-definition-packet:v1"
        || string_field(&record, "record_family")?
            != "disaster_resilience_outcome_floor_definition_packet"
        || int_field(&record, "pulse")? != 171
        || string_field(&record, "lane_id")? != "disaster-resilience"
        || string_field(&record, "contract_path")? != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&record, "outcome_floor_thresholds_gap_path")?
            != OUTCOME_FLOOR_THRESHOLDS_GAP_JSON_PATH
        || string_field(
            &record,
            "education_workforce_outcome_floor_definition_packet_path",
        )? != EDUCATION_WORKFORCE_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH
        || string_field(&record, "disaster_depth_card_path")? != DISASTER_DEPTH_CARD_JSON_PATH
        || string_field(&record, "lane_depth_explainability_tracker_path")?
            != LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH
    {
        return Err("disaster/resilience floor definition packet identity failed".to_string());
    }

    let status = record
        .get("source_custody_status")
        .and_then(serde_json::Value::as_object)
        .ok_or("disaster/resilience floor source custody status")?;
    for field in [
        "official_sources_only",
        "used_existing_captured_sources_only",
        "no_foia_or_records_request_submitted",
        "no_agency_or_person_contacted",
        "definition_packet_published",
    ] {
        if status.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!(
                "disaster/resilience floor status {field} must be true"
            ));
        }
    }
    for field in [
        "new_external_download_performed",
        "exposure_normalized_loss_distribution_ready",
        "prefunded_reserve_rule_ready",
        "base_supplemental_outlay_bridge_ready",
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "pass_fail_review_complete",
        "target_cost_ready",
        "solver_input_ready",
    ] {
        if status.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "disaster/resilience floor status {field} must be false"
            ));
        }
    }

    let policy = record
        .get("definition_policy")
        .and_then(serde_json::Value::as_object)
        .ok_or("disaster/resilience floor definition policy")?;
    for field in [
        "exposure_normalized_loss_distribution_required",
        "prefunded_reserve_rule_required_before_target_cost",
        "base_supplemental_and_declaration_to_outlay_bridge_required",
        "declarations_are_not_spending",
        "benefit_cost_ratios_are_not_realized_savings",
        "all_lower_cost_scenarios_must_pass_floors",
        "missing_values_remain_null",
        "blocked_gates_remain_false",
        "named_floor_concepts_are_not_threshold_values",
        "international_differences_not_savings",
        "no_fraud_inference",
    ] {
        if policy.get(field).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!(
                "disaster/resilience floor policy {field} must be true"
            ));
        }
    }

    let classes = record
        .get("required_floor_classes")
        .and_then(serde_json::Value::as_array)
        .ok_or("disaster/resilience required floor classes")?;
    let expected_classes = [
        "access_coverage",
        "quality_safety",
        "equity_distribution",
        "adequacy_resilience",
        "fiscal_delivery_feasibility",
    ];
    if classes.len() != expected_classes.len() {
        return Err("disaster/resilience required floor class count failed".to_string());
    }
    let observed_classes = classes
        .iter()
        .map(|row| string_field(row, "floor_class"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected_class_set = expected_classes
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if observed_classes != expected_class_set {
        return Err("disaster/resilience required floor class set failed".to_string());
    }
    for row in classes {
        for field in [
            "threshold_value",
            "baseline_value",
            "policy_value",
            "stress_value",
        ] {
            if row.get(field) != Some(&serde_json::Value::Null) {
                return Err(format!(
                    "disaster/resilience floor class {field} must be null"
                ));
            }
        }
        if row.get("passed").and_then(serde_json::Value::as_bool) != Some(false)
            || string_field(row, "review_status")? != "definition_only_not_thresholded"
        {
            return Err("disaster/resilience floor class must remain unpassed".to_string());
        }
    }

    let lane_floors = record
        .get("disaster_resilience_specific_floor_definitions")
        .and_then(serde_json::Value::as_array)
        .ok_or("disaster/resilience-specific floor definitions")?;
    let expected_lane_floors = [
        "life_safety_response",
        "recovery_continuity",
        "mitigation_resilience",
        "equity_unmet_need",
        "reserve_adequacy",
        "exposure_normalized_loss_distribution_delivery_feasibility",
    ];
    if lane_floors.len() != expected_lane_floors.len() {
        return Err("disaster/resilience-specific floor count failed".to_string());
    }
    let observed_lane_floors = lane_floors
        .iter()
        .map(|row| string_field(row, "floor_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected_lane_floor_set = expected_lane_floors
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if observed_lane_floors != expected_lane_floor_set {
        return Err("disaster/resilience-specific floor set failed".to_string());
    }
    for row in lane_floors {
        if row.get("threshold_value") != Some(&serde_json::Value::Null)
            || row.get("observed_value") != Some(&serde_json::Value::Null)
            || row.get("passed").and_then(serde_json::Value::as_bool) != Some(false)
        {
            return Err(
                "disaster/resilience-specific floors must remain null and unpassed".to_string(),
            );
        }
    }

    for object_name in ["blocked_inputs", "blocked_outputs"] {
        let object = record
            .get(object_name)
            .and_then(serde_json::Value::as_object)
            .ok_or(object_name)?;
        if object
            .values()
            .any(|value| value != &serde_json::Value::Null)
        {
            return Err(format!("{object_name} must remain null"));
        }
    }

    let summary = record
        .get("summary")
        .and_then(serde_json::Value::as_object)
        .ok_or("disaster/resilience floor summary")?;
    if summary
        .get("floor_classes")
        .and_then(serde_json::Value::as_i64)
        != Some(5)
        || summary
            .get("disaster_resilience_specific_floors")
            .and_then(serde_json::Value::as_i64)
            != Some(6)
    {
        return Err("disaster/resilience floor summary counts failed".to_string());
    }
    for field in [
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "all_floors_passed",
        "target_cost_ready",
        "reserve_rule_ready",
        "solver_input_ready",
    ] {
        if summary.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "disaster/resilience floor summary {field} must be false"
            ));
        }
    }

    let claims = record
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("disaster/resilience floor claims")?;
    if claims
        .get("definition_packet_published")
        .and_then(serde_json::Value::as_bool)
        != Some(true)
    {
        return Err("disaster/resilience floor packet publication flag failed".to_string());
    }
    for field in [
        "exposure_normalized_loss_distribution_ready",
        "event_normalized_outlay_path_ready",
        "base_supplemental_outlay_bridge_ready",
        "declaration_to_account_to_outlay_bridge_ready",
        "prefunded_reserve_rule_ready",
        "threshold_values_selected",
        "baseline_values_populated",
        "policy_values_populated",
        "stress_values_populated",
        "pass_fail_review_complete",
        "all_floors_passed",
        "target_cost_published",
        "reserve_path_published",
        "federal_effect_published",
        "gross_savings_published",
        "net_savings_published",
        "solver_input_ready",
        "public_rate_card_published",
        "department_cut_instruction_published",
        "technology_savings_claim_published",
        "balanced_budget_claim_published",
    ] {
        if claims.get(field).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "disaster/resilience floor claim {field} must be false"
            ));
        }
    }

    let reader = fs::read_to_string(
        root.join(DISASTER_RESILIENCE_OUTCOME_FLOOR_DEFINITION_PACKET_READER_PATH),
    )
    .map_err(|e| e.to_string())?;
    for phrase in [
        DISASTER_RESILIENCE_OUTCOME_FLOOR_DEFINITION_PACKET_JSON_PATH,
        "This disaster/resilience floor packet defines required floor concepts, but it does not set threshold values or pass/fail findings.",
        "Declarations are not spending, project amounts are not outlays, benefit-cost ratios are not realized savings, and none is a fraud finding.",
        "No lower-cost disaster/resilience scenario is admissible until life safety, recovery continuity, mitigation/resilience, equity/unmet need, reserve adequacy, exposure-normalized loss distribution, and delivery-feasibility floors are thresholded, sourced, reviewed, and passed.",
        "No target cost, reserve path, federal effect, gross savings, net savings, solver input, department-cut instruction, technology-savings claim, or balanced-budget claim is populated.",
        "No FOIA request, records request, form, email, phone call, or agency/person contact was submitted.",
        "not outcome-floor passage",
        "not an exposure-normalized loss distribution",
        "not an event-normalized outlay path",
        "not a prefunded reserve rule",
        "not a declaration-to-outlay bridge",
        "not a federal score",
        "not a target-cost selection",
        "not solver input",
        "not a rate calculation",
        "not a savings estimate",
        "not a fraud finding",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(phrase) {
            return Err(format!(
                "disaster/resilience floor reader missing phrase: {phrase}"
            ));
        }
    }

    Ok(())
}

