pub(crate) fn validate_claim_boundary(
    record: &serde_json::Value,
    label: &str,
    true_claims: &[&str],
) -> Result<(), String> {
    let claims = record
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| format!("{label} claims"))?;
    for (field, value) in claims {
        let expected = true_claims.contains(&field.as_str());
        if value
            .as_bool()
            .ok_or_else(|| format!("{label} claim bool"))?
            != expected
        {
            return Err(format!("{label} claim boundary failed: {field}"));
        }
    }
    Ok(())
}

pub(crate) fn validate_started_track(
    root: &Path,
    path: &str,
    record_id: &str,
    wave_id: &str,
    pulse: i64,
    work_packages: usize,
    active_index: usize,
) -> Result<serde_json::Value, String> {
    let record = read_json_artifact(root, path)?;
    if string_field(&record, "record_id")? != record_id
        || string_field(&record, "track_wave_id")? != wave_id
        || int_field(&record, "pulse")? != pulse
    {
        return Err(format!("{wave_id} identity failed"));
    }
    let packages = record
        .get("work_packages")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| format!("{wave_id} packages"))?;
    if packages.len() != work_packages {
        return Err(format!("{wave_id} start package boundary failed"));
    }
    for (index, package) in packages.iter().enumerate() {
        let status = string_field(package, "status")?;
        let valid = if index < active_index {
            status == "complete" || status.starts_with("not_required_")
        } else if index == active_index {
            status == "in_progress"
        } else {
            status == "queued"
        };
        if !valid {
            return Err(format!("{wave_id} package status failed at index {index}"));
        }
    }
    Ok(record)
}

pub(crate) fn validate_bounded_lane_baseline(
    record: &serde_json::Value,
    label: &str,
    pulse: i64,
    health: bool,
) -> Result<(), String> {
    if int_field(record, "pulse")? != pulse
        || string_field(record, "source_path")?
            != "data/derived/breadth_benchmark_matrix/current_law_17_row_pbd_fy2025_2031_context_path.v1.draft.json"
    {
        return Err(format!("{label} baseline identity failed"));
    }
    let rows = record
        .get("annual_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| format!("{label} annual rows"))?;
    if rows.len() != 11 {
        return Err(format!("{label} must have eleven annual rows"));
    }
    for (index, row) in rows.iter().enumerate() {
        let year = 2025 + index as i64;
        if int_field(row, "fiscal_year")? != year {
            return Err(format!("{label} year ordering failed: {year}"));
        }
        if index < 7 {
            if string_field(row, "observation")? != "exact_at_source_display_precision" {
                return Err(format!("{label} exact observation failed: {year}"));
            }
            if health {
                let health_value = int_field(row, "health_550_outlays_millions")?;
                let medicare_value = int_field(row, "medicare_570_outlays_millions")?;
                if int_field(row, "combined_health_medicare_outlays_millions")?
                    != health_value + medicare_value
                {
                    return Err(format!("{label} component sum failed: {year}"));
                }
            } else {
                int_field(row, "function_500_outlays_millions")?;
            }
        } else {
            let null_fields = if health {
                [
                    "health_550_outlays_millions",
                    "medicare_570_outlays_millions",
                    "combined_health_medicare_outlays_millions",
                ]
                .as_slice()
            } else {
                ["function_500_outlays_millions"].as_slice()
            };
            for field in null_fields {
                if !row.get(field).is_some_and(serde_json::Value::is_null) {
                    return Err(format!("{label} missing value populated: {year} {field}"));
                }
            }
        }
    }
    let reconciliation = record
        .get("reconciliation")
        .ok_or_else(|| format!("{label} reconciliation"))?;
    if int_field(reconciliation, "exact_years")? != 7
        || int_field(reconciliation, "explicit_null_years")? != 4
        || !bool_field(reconciliation, "bounded_horizon_record_complete")?
        || bool_field(reconciliation, "full_numeric_horizon_ready")?
    {
        return Err(format!("{label} bounded reconciliation failed"));
    }
    if record
        .get("blocked_outputs")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| format!("{label} blocked outputs"))?
        .values()
        .any(|value| !value.is_null())
    {
        return Err(format!("{label} blocked output must remain null"));
    }
    Ok(())
}

pub(crate) fn validate_blocked_outputs_null(record: &serde_json::Value, label: &str) -> Result<(), String> {
    if record
        .get("blocked_outputs")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| format!("{label} blocked outputs"))?
        .values()
        .any(|value| !value.is_null())
    {
        return Err(format!("{label} blocked output must remain null"));
    }
    Ok(())
}

